import * as z from "zod/v4";
import { defineTool } from "../../../tools.js";
const postCard = defineTool({
    description: [
        "Publish or update a collapsible task card in the thread.",
        "Same id updates the same card. That is progress.",
        "status is pending, in_progress, complete, or error.",
        "Use a card for work that should stay on screen and change.",
        "Do not use it as the reply; that is post-update.",
        "The tool records nothing. The channel watching this turn renders the card.",
    ].join(" "),
    inputSchema: z.object({
        id: z.string().trim().min(1),
        title: z.string().trim().min(1),
        status: z.enum(["pending", "in_progress", "complete", "error"]),
        details: z.string().trim().min(1).optional(),
    }),
    execute: ({ id, title, status, details }) => ({
        id,
        title,
        status,
        details,
    }),
});
export default postCard;
